import sys

sys.setrecursionlimit(20000)

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def transformTree(root):
    current_sum = [0]

    def reverse_inorder(node):
        if node is None:
            return
        reverse_inorder(node.right)
        current_sum[0] += node.val
        node.val = current_sum[0] - node.val
        reverse_inorder(node.left)

    reverse_inorder(root)
    return root

def inorder_traversal(root, result):
    if root is None:
        return
    inorder_traversal(root.left, result)
    result.append(str(root.val))
    inorder_traversal(root.right, result)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    if n == 0:
        print("")
        return

    values = list(map(int, input_data[1:n+1]))

    nodes = {}
    root = None

    for i in range(n):
        val = values[i]
        if val not in nodes:
            nodes[val] = Node(val)

    edges = []
    idx = n + 1
    while idx < len(input_data):
        u_str = input_data[idx]
        v_str = input_data[idx+1]
        if u_str == 'N' or v_str == 'N':
            idx += 2
            continue
        u, v = int(u_str), int(v_str)
        edges.append((u, v))
        idx += 2

    if n > 0:
        root = nodes[values[0]]

    for u, v in edges:
        parent = nodes[u]
        child = nodes[v]
        if child.val < parent.val:
            parent.left = child
        else:
            parent.right = child

    transformTree(root)

    result = []
    inorder_traversal(root, result)
    print(" ".join(result))

if __name__ == "__main__":
    main()
